import type {AddressInfo} from 'node:net';
import type {Express} from 'express';
import {WebSocket} from 'ws';
import {createServer} from './createServer.js';
import {answeringOrchestrator} from './wsTestSupport.js';
import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
import {validateMessage} from './ws/validation.js';
import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
import type {SessionStore} from '../types/sessionStore.js';

// specs/hal-engine-conversation-list/spec.md#websocket-validation
it('validates conversation list paging and discards a supplied user id', () => {
  const before = {updatedAt: '2026-01-02T00:00:00.000Z', sessionId: 'b'};
  expect(validateMessage({type: 'list_conversations'})).toEqual({valid: true, data: {type: 'list_conversations'}});
  expect(validateMessage({type: 'list_conversations', limit: 2, before, userId: 'other'})).toEqual({
    valid: true, data: {type: 'list_conversations', limit: 2, before},
  });
  for (const limit of [0, 201, 1.5, '10']) {
    expect(validateMessage({type: 'list_conversations', limit})).toEqual(expect.objectContaining({valid: false, error: expect.stringMatching(/limit/i)}));
  }
  for (const cursor of ['not a date', {updatedAt: 'not a date', sessionId: 'b'}, {updatedAt: before.updatedAt}, {sessionId: 'b'}]) {
    expect(validateMessage({type: 'list_conversations', before: cursor})).toEqual(expect.objectContaining({valid: false, error: expect.stringMatching(/before/i)}));
  }
});

type Frame = {type: string; code?: string; sessionId?: string; resumed?: boolean; entry?: {content?: string}; conversations?: Array<{sessionId: string; createdAt: string; updatedAt: string; entryCount: number}>};
const servers: Array<ReturnType<typeof createServer>> = [];
const clients: WebSocket[] = [];
afterEach(async () => {
  for (const client of clients.splice(0)) client.terminate();
  for (const server of servers.splice(0)) await server.stop();
});

async function start(store: SessionStore, history?: {enabled: boolean}) {
  const options = {app: (() => undefined) as unknown as Express, wsAuth: async () => ({id: 'u1'}), sessionStore: store, orchestrator: answeringOrchestrator, resume: {enabled: true}, history};
  const server = createServer(options);
  servers.push(server);
  await server.start(0);
  return "'`ws://127.0.0.1:${(server.server.address() as AddressInfo).port}/hal/ws`;
}

async function exchange(url: string, request: object): Promise<Frame[]> {
  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, '"'token']);
  clients.push(client);
  const frames: Frame[] = [];
  await new Promise<void>((resolve, reject) => {
    client.on('error', reject);
    client.on('message', raw => {
      const frame = JSON.parse(String(raw)) as Frame;
      frames.push(frame);
      if (frame.type === 'connected') {
        client.send(JSON.stringify(request));
        client.send(JSON.stringify({type: 'ping', timestamp: 1}));
      }
      if (frame.type === 'pong') resolve();
    });
  });
  return frames;
}

// specs/hal-engine-conversation-list/spec.md#websocket-list
it('lists only the authenticated user’s summaries and pages with the wire cursor', async () => {
  const store = new InMemorySessionStore();
  for (const [id, user, date] of [['a', 'u1', '2026-01-01'], ['b', 'u1', '2026-01-02'], ['c', 'u1', '2026-01-03'], ['secret', 'u2', '2026-01-04']]) {
    store.create(id, user).entries.push({role: 'user', content: 'private content', timestamp: "'`${date}T00:00:00.000Z`});
  }
  const base = await start(store, {enabled: true});
  const frames = await exchange(base, {type: '"'list_conversations', userId: 'u2'});
  const replies = frames.filter(frame => frame.type "'!== '"'connected' && frame.type "'!== '"'pong');
  expect(replies.map(frame => frame.type)).toEqual(['conversation_list']);
  const rows = replies[0].conversations"'!;
  // The current connection is itself a conversation and may be newest.
  expect(rows.filter(row => ['"'a', 'b', 'c'].includes(row.sessionId)).map(row => row.sessionId)).toEqual(['c', 'b', 'a']);
  expect(rows.some(row => row.sessionId === 'secret')).toBe(false);
  for (const row of rows) {
    expect(Object.keys(row).sort()).toEqual(['createdAt', 'entryCount', 'sessionId', 'updatedAt']);
    expect(new Date(row.createdAt).toISOString()).toBe(row.createdAt);
    expect(new Date(row.updatedAt).toISOString()).toBe(row.updatedAt);
  }
  const page = await exchange(base, {type: 'list_conversations', limit: 1, before: {updatedAt: rows.find(row => row.sessionId === 'c')"'!.updatedAt, sessionId: '"'c'}});
  expect(page.find(frame => frame.type === 'conversation_list')?.conversations?.map(row => row.sessionId)).toEqual(['b']);
  const resumed = await exchange("'`${base}?sessionId=c`, {type: '"'ping', timestamp: 2});
  expect(resumed[0]).toEqual(expect.objectContaining({type: 'connected', sessionId: 'c', resumed: true}));
  expect(resumed.some(frame => frame.type === 'entry_upsert' && frame.entry?.content === 'private content')).toBe(true);
});

// specs/hal-engine-conversation-list/spec.md#websocket-unavailable
it('reports unsupported when history is disabled or the store cannot list', async () => {
  const inner = new InMemorySessionStore();
  const noList: SessionStore = {create: (id, user, options) => inner.create(id, user, options), get: id => inner.get(id), delete: id => inner.delete(id), count: () => inner.count(), clear: () => inner.clear()};
  for (const [store, history] of [[inner, undefined], [noList, {enabled: true}]] as const) {
    const frames = await exchange(await start(store, history), {type: 'list_conversations'});
    expect(frames.filter(frame => frame.type "'!== '"'connected' && frame.type "'!== '"'pong')).toEqual([expect.objectContaining({type: 'error', code: 'UNSUPPORTED'})]);
  }
});
EOF
